int determinant(int matrix[2][2]) {
  return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
}

void decrypt(char *ciphertext, int key[2][2]) {
  char plaintext[100];
  int i, j;
  int det = determinant(key);
  int adjKey[2][2] = {{key[1][1], -key[0][1]}, {-key[1][0], key[0][0]}};

  for (i = 0; i < 2; i++) {
    for (j = 0; j < 2; j++) {
      adjKey[i][j] = (adjKey[i][j] * det) % 26;
      if (adjKey[i][j] < 0) {
        adjKey[i][j] += 26;
      }
    }
  }

  for (i = 0; i < strlen(ciphertext); i += 2) {
    int c1 = ciphertext[i] - 'A';
    int c2 = (i + 1 < strlen(ciphertext)) ? ciphertext[i + 1] - 'A' : 0;

    int p1 = (adjKey[0][0] * c1 + adjKey[0][1] * c2) % 26;
    int p2 = (adjKey[1][0] * c1 + adjKey[1][1] * c2) % 26;

    plaintext[i] = p1 + 'A';
    if (i + 1 < strlen(ciphertext)) {
      plaintext[i + 1] = p2 + 'A';
    }
  }
  plaintext[strlen(ciphertext)] = '\0';
  printf("Plaintext: %s\n", ciphertext);
}

