#include <stdio.h>
#include <string.h>

unsigned char S[256];

void rc4_init(unsigned char *key, int klen) {
    int i, j = 0;
    unsigned char t;
    for (i = 0; i < 256; i++) S[i] = i;                 // 1. fill S with 0..255
    for (i = 0; i < 256; i++) {                         // 2. shuffle using the key
        j = (j + S[i] + key[i % klen]) % 256;
        t = S[i]; S[i] = S[j]; S[j] = t;
    }
}

void rc4_crypt(unsigned char *data, int len) {
    int i = 0, j = 0, n;
    unsigned char t;
    for (n = 0; n < len; n++) {                         // 3. generate keystream, XOR
        i = (i + 1) % 256;
        j = (j + S[i]) % 256;
        t = S[i]; S[i] = S[j]; S[j] = t;
        data[n] ^= S[(S[i] + S[j]) % 256];
    }
}

int main() {
    unsigned char key[] = "secretkey";
    unsigned char text[] = "Hello World";
    int klen = strlen((char *)key), len = strlen((char *)text);

    printf("Plaintext : %s\n", text);

    rc4_init(key, klen);
    rc4_crypt(text, len);
    printf("Ciphertext: ");
    for (int i = 0; i < len; i++) printf("%02x", text[i]);

    rc4_init(key, klen);          // reset the state, then the same function decrypts
    rc4_crypt(text, len);
    printf("\nDecrypted : %s\n", text);
    return 0;
}

#include <stdio.h>

// (base^exp) % mod, done step by step so numbers never overflow
long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp = exp / 2;
    }
    return result;
}

int main() {
    long long p = 61, q = 53;           // two primes
    long long n = p * q;                // 3233
    long long phi = (p - 1) * (q - 1);  // 3120
    long long e = 17, d = 1;            // e must be coprime with phi

    while ((e * d) % phi != 1) d++;     // find d: e*d = 1 (mod phi)

    long long msg = 12;
    long long enc = power(msg, e, n);
    long long dec = power(enc, d, n);

    printf("Public Key : (%lld, %lld)\n", e, n);
    printf("Private Key: (%lld, %lld)\n", d, n);
    printf("Original   : %lld\n", msg);
    printf("Encrypted  : %lld\n", enc);
    printf("Decrypted  : %lld\n", dec);
    return 0;
}

