#define ROL(x, n) (((x) << (n)) | ((x) >> (32 - (n))))

int main() {
  char *msg = "Hello, World!"; // must be 55 characters or fewer
  int len = strlen(msg);

  // 1. Padding: message + 0x80 + zeros + length in bits (one 64-byte block)
  uint8_t block[64] = {0};
  memcpy(block, msg, len);
  block[len] = 0x80;
  block[62] = (len * 8) >> 8;
  block[63] = (len * 8) & 0xFF;

  // 2. Message schedule: 16 words from the block, expanded to 80
  uint32_t w[80];
  for (int i = 0; i < 16; i++)
    w[i] = ((uint32_t)block[4 * i] << 24) | ((uint32_t)block[4 * i + 1] << 16) |
           ((uint32_t)block[4 * i + 2] << 8) | block[4 * i + 3];
  for (int i = 16; i < 80; i++)
    w[i] = ROL(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);

  // 3. Main loop: 80 rounds
  uint32_t h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476,
           h4 = 0xC3D2E1F0;
  uint32_t a = h0, b = h1, c = h2, d = h3, e = h4, f, k, temp;

  for (int i = 0; i < 80; i++) {
    if (i < 20) {
      f = (b & c) | (~b & d);
      k = 0x5A827999;
    } else if (i < 40) {
      f = b ^ c ^ d;
      k = 0x6ED9EBA1;
    } else if (i < 60) {
      f = (b & c) | (b & d) | (c & d);
      k = 0x8F1BBCDC;
    } else {
      f = b ^ c ^ d;
      k = 0xCA62C1D6;
    }

    temp = ROL(a, 5) + f + e + k + w[i];
    e = d;
    d = c;
    c = ROL(b, 30);
    b = a;
    a = temp;
  }

  // 4. Add to starting values and print
  printf("Message Digest = %08x%08x%08x%08x%08x\n", h0 + a, h1 + b, h2 + c,
         h3 + d, h4 + e);
  return 0;
}

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define ROL(x, n) (((x) << (n)) | ((x) >> (32 - (n))))

int main() {
  char *msg = "Hello, World!"; // must be 55 characters or fewer
  int len = strlen(msg);

  // 1. Padding: message + 0x80 + zeros + length in bits (one 64-byte block)
  uint8_t block[64] = {0};
  memcpy(block, msg, len);
  block[len] = 0x80;
  block[56] = (len * 8) & 0xFF;
  block[57] = (len * 8) >> 8;

  // 2. Split into 16 words (little-endian)
  uint32_t w[16];
  for (int i = 0; i < 16; i++)
    w[i] = block[4 * i] | ((uint32_t)block[4 * i + 1] << 8) |
           ((uint32_t)block[4 * i + 2] << 16) |
           ((uint32_t)block[4 * i + 3] << 24);

  // 3. 64 rounds
  int s[4][4] = {
      {7, 12, 17, 22}, {5, 9, 14, 20}, {4, 11, 16, 23}, {6, 10, 15, 21}};
  uint32_t h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476;
  uint32_t a = h0, b = h1, c = h2, d = h3, f, k;
  int g;

  for (int i = 0; i < 64; i++) {
    if (i < 16) {
      f = (b & c) | (~b & d);
      g = i;
    } else if (i < 32) {
      f = (d & b) | (~d & c);
      g = (5 * i + 1) % 16;
    } else if (i < 48) {
      f = b ^ c ^ d;
      g = (3 * i + 5) % 16;
    } else {
      f = c ^ (b | ~d);
      g = (7 * i) % 16;
    }

    k = (uint32_t)(fabs(sin(i + 1)) * 4294967296.0); // the 64 constants
    f = f + a + k + w[g];
    a = d;
    d = c;
    c = b;
    b = b + ROL(f, s[i / 16][i % 4]);
  }

  // 4. Add to starting values, print each word byte-by-byte (little-endian)
  uint32_t out[4] = {h0 + a, h1 + b, h2 + c, h3 + d};
  printf("Message = %s\n", msg);
  printf("Message Digest = ");
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 4; j++)
      printf("%02x", (out[i] >> (8 * j)) & 0xFF);
  printf("\n");
  return 0;
}
